            if (!name && error_is(b->ctx, "AttributeError")) { spy_clear_error(b->ctx); name = attribute(b->ctx, function, "__name__"); }
            if (!name && error_is(b->ctx, "AttributeError")) spy_clear_error(b->ctx);
