    SPYValue *result = first ? rich_method(c, reflected[op], right, left) : NULL;
    if (!result && !c->error_type[0]) result = rich_method(c, op, left, right);
    if (!first && !result && !c->error_type[0]) result = rich_method(c, reflected[op], right, left);
