    if (self->type != SPY_BYTEARRAY) return string_search(c, self, method, argc - 1, argv + 1);
    SPYValue view = {.ctx = self->ctx, .type = SPY_BYTES, .as.string = self->as.string};
    return string_search(c, &view, method, argc - 1, argv + 1);
