        SPYValue *method = special_method(c, fn, "__call__");
        if (method) { result = call_keywords(c, method, argc, argv, keywords); spy_release(method); }
        else if (!c->error_type[0]) spy_error(c, "TypeError", "metaclass has no __call__");
