    SPYValue *method = exit ? special_method(c, manager, "__enter__") : NULL;
    if (manager && !method && !c->error_type[0]) manager_error(c, manager, 0, exit != NULL);
    SPYValue *enter = method ? spy_call(c, method, 0, NULL) : NULL;
    spy_release(method);
