        ((flags & PF_ALT) && hex && puts_buffer(&out, ch == 'o' ? "0o" : ch == 'x' ? "0x" : "0X"));
    for (size_t i = count; !status && prec > 0 && i < (size_t)prec; i++) status = puts_buffer(&out, "0");
    status = status || append(&out, text + negative, count);
