    case SET_POP: {
        if (!self->as.map.len) return spy_error(c, "KeyError", "pop from an empty set");
        SPYValue *item = spy_retain(map_items(self)[0].key);
        set_remove_at(self, 0);
        return item;
    }
    case SET_CLEAR:
        while (self->as.map.len) set_remove_at(self, map_used(self) - 1);
        return spy_none(c);
