    if (copy && ndim == m->as.memory.ndim) memcpy(copy->as.memory.layout, m->as.memory.layout, 2 * (size_t)ndim * sizeof(ptrdiff_t));
    if (copy) copy->as.memory.offset = m->as.memory.offset;
