                if (eq) { result = spy_call(c, eq, 1, argv); spy_release(eq); }
                else if (c->error_type[0]) return NULL;
                else result = spy_retain(self == argv[0] ? c->booleans[1] : c->not_implemented);
                if (!result || result == c->not_implemented) return result;
