void spy_context_free(SPYContext *c) {
    if (!c) return;
    /* Context destruction invalidates every value. Free storage directly so
     * shutdown cannot recurse through an arbitrarily deep object graph. */
    c->weak_len = 0;
    /* Kept environments' keys are values freed below. */
    for (size_t i = 0; i < c->frames_cap; i++)
        if (c->frames[i].kept) { free(map_storage(c->frames[i].kept)); free(c->frames[i].kept); }
    c->frames_cap = 0;
    while (c->values) free_value(c->values);
    free(c->weak); free(c->weak_calls); free(c->finalize_calls); free(c->cells); free(c->frames); free(c->repr_stack);
    for (size_t i = 0; i < c->host_modules_len; i++) free(c->host_modules[i].name);
    free(c->host_modules);
    for (size_t i = 0; i < c->mounts_len; i++) { free(c->mounts[i].host); free(c->mounts[i].path); }
    free(c->mounts);
#if SPY_FILES
    for (size_t i = 0; i < c->files_len; i++) close(c->files[i]);
#endif
    free(c->files); free(c->error_display);
    for (size_t i = 0; i < sizeof(c->tuple_cache) / sizeof(*c->tuple_cache); i++) free(c->tuple_cache[i]);
    for (int small = 0; small < 2; small++)
        while (c->spare[small]) {
            SPYValue *v = c->spare[small];
            cache_take(v, small ? SMALL_VALUE : sizeof(*v)); c->spare[small] = v->next; free(v);
        }
    while (c->spare_entries_len) free(c->spare_entries[--c->spare_entries_len]);
    if (c->spare_machine) { free(c->spare_machine->blocks); free(c->spare_machine->stack); free(c->spare_machine); }
    free(c);
}
void spy_set_output(SPYContext *c, SPYWrite write, void *data) { c->write = write; c->write_data = data; c->flush = NULL; }
void spy_set_flush(SPYContext *c, SPYFlush flush) { c->flush = flush; }
void spy_set_error_output(SPYContext *c, SPYWrite write, void *data) { c->error_write = write; c->error_data = data; }
void spy_set_module_loader(SPYContext *c, SPYModuleLoader loader, void *data) { c->loader = loader; c->loader_data = data; }
void spy_set_input(SPYContext *c, SPYReadLine read_line, void *data) { c->read_line = read_line; c->read_data = data; }
void spy_set_step_limit(SPYContext *c, size_t limit) { c->step_limit = limit; attend(c); }
void spy_set_optimize(SPYContext *c, int level) { c->optimize = level < 0 ? 0 : level > 2 ? 2 : level; }
static SPYValue *eval_source(SPYContext *c, const char *source, const char *filename, int interactive) {
    spy_clear_error(c); c->steps = 0;
    SPYValue *unit = parse(c, source, filename ? filename : "<string>");
    if (!unit) return NULL;
    Frame frame = {c->globals, unit, interactive};
    Result result = execute_module(c, &frame);
    spy_release(unit);
    /* Deaths in the last statement have no later statement boundary. */
    if (result.flow != FLOW_ERROR && (c->weak_calls_len || c->finalize_calls_len)) weak_callbacks(c);
    if (result.flow == FLOW_ERROR) { spy_release(result.value); return NULL; }
    return result.value ? result.value : spy_none(c);
}
SPYValue *spy_eval(SPYContext *c, const char *source, const char *filename) {
    return eval_source(c, source, filename, 0);
}
SPYValue *spy_eval_interactive(SPYContext *c, const char *source, const char *filename) {
    return eval_source(c, source, filename, 1);
}
int spy_exec(SPYContext *c, const char *source, const char *filename) {
    SPYValue *v = spy_eval(c, source, filename);
    if (!v) return -1;
    spy_release(v);
    return 0;
}
/* Embedding API over the evaluator's own operations. */
SPYValue *spy_native(SPYContext *c, const char *name, SPYNativeKeywords call, void *data, void (*release)(void *)) {
    SPYValue *v = value_new(c, SPY_NATIVE);
    if (!v) { if (release) release(data); return NULL; }
    v->as.native.kwcall = call; v->as.native.data = data; v->as.native.release = release;
    v->as.native.name = spy_string(c, name, strlen(name));
    if (!v->as.native.name) { spy_release(v); return NULL; }
    return v;
}
SPYValue *spy_call_keywords(SPYContext *c, SPYValue *fn, size_t argc, SPYValue *const *argv, SPYValue *keywords) {
    if (keywords && (!same_context(c, keywords) || !is_dict(keywords))) return spy_error(c, "TypeError", "keywords must be a dict");
    if (!same_contexts(c, argc, argv)) return NULL;
    return call_keywords(c, fn, argc, argv, keywords && keywords->as.map.len ? keywords : NULL);
}
SPYValue *spy_tuple(SPYContext *c, size_t n, SPYValue *const *items) {
    SPYValue *tuple = value_new(c, SPY_TUPLE);
    for (size_t i = 0; tuple && i < n; i++)
        if (!same_context(c, items[i]) || sequence_append(c, tuple, items[i])) { spy_release(tuple); return NULL; }
    return tuple;
}
SPYValue *spy_dict(SPYContext *c) { return value_new(c, SPY_DICT); }
SPYValue *spy_get_item(SPYContext *c, SPYValue *v, SPYValue *key) {
    return same_context(c, v) && same_context(c, key) ? get_index(c, v, key) : NULL;
}
int spy_set_item(SPYContext *c, SPYValue *v, SPYValue *key, SPYValue *item) {
    return same_context(c, v) && same_context(c, key) && same_context(c, item) ? set_index(c, v, key, item) : -1;
}
SPYValue *spy_get_attr(SPYContext *c, SPYValue *v, const char *name) {
    return same_context(c, v) ? attribute(c, v, name) : NULL;
}
int spy_set_attr(SPYContext *c, SPYValue *v, const char *name, SPYValue *item) {
    return same_context(c, v) && same_context(c, item) ? set_attribute(c, v, name, item) : -1;
}
SPYValue *spy_iter(SPYContext *c, SPYValue *v) { return same_context(c, v) ? get_iterator(c, v) : NULL; }
SPYValue *spy_next(SPYContext *c, SPYValue *iterator) { return same_context(c, iterator) ? iterator_next(c, iterator) : NULL; }
SPYValue *spy_str(SPYContext *c, SPYValue *v) { return same_context(c, v) ? stringify(c, v, 0) : NULL; }
SPYValue *spy_error_value(SPYContext *c) {
    if (!c->error_type[0]) return NULL;
    ErrorState state = take_error(c);
    SPYValue *value = spy_retain(state.value);
    restore_error(c, &state);
    return value;
}
SPYValue *spy_raise(SPYContext *c, SPYValue *exception) {
    return same_context(c, exception) ? raise_value(c, exception) : NULL;
}
/* Host files. open() is the intrinsic io layer over these _spy primitives,
 * which reach only mounted directories and descriptors this context opened. */
/* input([prompt]): flush, write str(prompt), and read a line from the host's
 * reader without its line ending. No reader, or its end, is EOFError. */
static SPYValue *input_builtin(SPYContext *c, size_t argc, SPYValue *const *argv, SPYValue *keywords, void *data) {
    (void)data;
    if (keywords && keywords->as.map.len) return spy_error(c, "TypeError", "input() takes no keyword arguments");
    if (argc > 1) return errorf(c, "TypeError", "input expected at most 1 argument, got %zu", argc);
    if (c->flush && c->flush(c->write_data)) return spy_error(c, "OSError", "output flush failed");
    if (argc) {
        SPYValue *text = stringify(c, argv[0], 0);
        int status = text ? print_text(c, NULL, text) : -1;
        spy_release(text);
        if (status || c->error_type[0]) return NULL;
        if (c->flush && c->flush(c->write_data)) return spy_error(c, "OSError", "output flush failed");
    }
    char *line = c->read_line ? c->read_line(c->read_data) : NULL;
    if (!line) return c->error_type[0] ? NULL : spy_error(c, "EOFError", "EOF when reading a line");
    size_t len = strlen(line);
    if (len && line[len - 1] == '\n') len--;
    if (len && line[len - 1] == '\r') len--;
    SPYValue *result = spy_string(c, line, len);
    free(line);
    return result;
}
static SPYValue *open_builtin(SPYContext *c, size_t argc, SPYValue *const *argv, SPYValue *keywords, void *data) {
    (void)data;
    if (!argc && !(keywords && name_local(keywords, "file")))
        return spy_error(c, "TypeError", "open() missing required argument 'file' (pos 1)");
    SPYValue *fn = intrinsic(c, "open");
    return fn ? spy_call_keywords(c, fn, argc, argv, keywords) : NULL;
}
#if SPY_FILES
/* Raise the OSError subclass for errno code, as PyErr_SetFromErrnoWithFilenameObject. */
static SPYValue *file_error(SPYContext *c, int code, SPYValue *filename) {
    const char *text = strerror(code);
    SPYValue *args[] = {spy_int(c, code), spy_string(c, text, strlen(text)), filename};
    SPYValue *error = args[0] && args[1] ? new_exception(c, name_local(c->classes, "OSError"), filename ? 3 : 2, args) : NULL;
    if (error) raise_value(c, error);
    spy_release(error); spy_release(args[0]); spy_release(args[1]);
    return NULL;
}
/* Lexically normalize an absolute path in place: no empty, '.', or '..' components. */
static void normalize_path(char *path) {
    char *out = path, *in = path;
    while (*in) {
        while (*in == '/') in++;
        const char *start = in;
        while (*in && *in != '/') in++;
        size_t len = (size_t)(in - start);
        if (!len || (len == 1 && start[0] == '.')) continue;
        if (len == 2 && start[0] == '.' && start[1] == '.') {
            while (out > path && *--out != '/') {}
            continue;
        }
        *out++ = '/';
        memmove(out, start, len);
        out += len;
    }
    if (out == path) *out++ = '/';
    *out = 0;
}
/* Whether path is root or lies under it, component-wise. */
static int path_within(const char *path, const char *root) {
    size_t len = strlen(root);
    if (len == 1) return 1;
    return !strncmp(path, root, len) && (path[len] == 0 || path[len] == '/');
}
/* The host path of a guest path inside the mount that holds it, with the
 * final component unresolved only when it does not exist yet; NULL with errno. */
static char *mount_resolve(SPYContext *c, const char *path, int writing) {
    if (!c->mounts_len) { errno = EACCES; return NULL; }
    size_t size = strlen(path) + strlen(c->mounts[0].path) + 2;
    char *guest = malloc(size);
    if (!guest) { errno = ENOMEM; return NULL; }
    if (path[0] == '/') memcpy(guest, path, strlen(path) + 1);
    else snprintf(guest, size, "%s/%s", c->mounts[0].path, path);
    normalize_path(guest);
    struct Mount *mount = NULL;
    for (size_t i = 0; i < c->mounts_len; i++)
        if (path_within(guest, c->mounts[i].path) && (!mount || strlen(c->mounts[i].path) > strlen(mount->path))) mount = &c->mounts[i];
    if (!mount) { free(guest); errno = EACCES; return NULL; }
    if (writing && (mount->flags & SPY_MOUNT_READ_ONLY)) { free(guest); errno = EROFS; return NULL; }
    const char *rest = guest + (strlen(mount->path) == 1 ? 0 : strlen(mount->path));
    size = strlen(mount->host) + strlen(rest) + 1;
    char *host = malloc(size);
    if (!host) { free(guest); errno = ENOMEM; return NULL; }
    snprintf(host, size, "%s%s", strcmp(mount->host, "/") || !*rest ? mount->host : "", rest);
    free(guest);
    char *real = realpath(host, NULL);
    if (!real && errno == ENOENT) {
        char *slash = strrchr(host, '/');
        *slash = 0;
        char *parent = realpath(*host ? host : "/", NULL);
        if (parent) {
            size = strlen(parent) + strlen(slash + 1) + 2;
            if ((real = malloc(size))) snprintf(real, size, "%s/%s", strcmp(parent, "/") ? parent : "", slash + 1);
            else errno = ENOMEM;
            free(parent);
        }
    }
    free(host);
    if (real && !path_within(real, mount->host)) { free(real); errno = EACCES; return NULL; }
    return real;
}
static ptrdiff_t file_index(SPYContext *c, SPYValue *v, int *fd) {
    int64_t n;
    if (index_value(c, v, &n)) return -1;
    for (size_t i = 0; i < c->files_len; i++)
        if (c->files[i] == n) { *fd = (int)n; return (ptrdiff_t)i; }
    file_error(c, EBADF, NULL);
    return -1;
}
#endif
enum { FILE_OPEN, FILE_READ, FILE_WRITE, FILE_SEEK, FILE_TRUNCATE, FILE_CLOSE };
static SPYValue *file_native(SPYContext *c, size_t argc, SPYValue *const *argv, void *data) {
    static const char *const names[] = {"_file_open", "_file_read", "_file_write", "_file_seek", "_file_truncate", "_file_close"};
    static const size_t counts[] = {2, 2, 2, 3, 2, 1};
    int id = (int)(intptr_t)data;
    if (argc != counts[id]) return errorf(c, "TypeError", "%s() takes %zu arguments (%zu given)", names[id], counts[id], argc);
#if SPY_FILES
    if (id == FILE_OPEN) {
        SPYValue *path = builtin_value(c, argv[0], SPY_STRING), *mode = builtin_value(c, argv[1], SPY_STRING);
        if (!path) path = builtin_value(c, argv[0], SPY_BYTES);
        if (!path || !mode) return spy_error(c, "TypeError", "_file_open() needs a path and a mode string");
        if (strlen(path->as.string.data) != path->as.string.len) return spy_error(c, "ValueError", "embedded null byte");
        const char *m = mode->as.string.data;
        int plus = strchr(m, '+') != NULL, flags = plus ? O_RDWR : m[0] == 'r' ? O_RDONLY : O_WRONLY;
        if (m[0] == 'w') flags |= O_CREAT | O_TRUNC;
        else if (m[0] == 'a') flags |= O_CREAT | O_APPEND;
        else if (m[0] == 'x') flags |= O_CREAT | O_EXCL;
        else if (m[0] != 'r') return errorf(c, "ValueError", "invalid mode: '%s'", m);
        if (c->files_len == c->files_cap) {
            size_t cap = c->files_cap ? c->files_cap * 2 : 8;
            int *files = realloc(c->files, cap * sizeof(*files));
            if (!files) return spy_error(c, "MemoryError", "out of memory");
            c->files = files; c->files_cap = cap;
        }
        char *real = mount_resolve(c, path->as.string.data, plus || m[0] != 'r');
        if (!real) return file_error(c, errno, argv[0]);
        int fd = open(real, flags | O_CLOEXEC | O_NOFOLLOW, 0666), code = errno;
        free(real);
        if (fd < 0) return file_error(c, code, argv[0]);
        struct stat st;
        if (fstat(fd, &st) || S_ISDIR(st.st_mode)) {
            code = S_ISDIR(st.st_mode) ? EISDIR : errno;
            close(fd);
            return file_error(c, code, argv[0]);
        }
        c->files[c->files_len++] = fd;
        return spy_int(c, fd);
    }
    int fd;
    ptrdiff_t at = file_index(c, argv[0], &fd);
    if (at < 0) return NULL;
    if (id == FILE_CLOSE) {
        c->files[at] = c->files[--c->files_len];
        return close(fd) ? file_error(c, errno, NULL) : spy_none(c);
    }
    if (id == FILE_WRITE) {
        SPYValue *bytes = builtin_value(c, argv[1], SPY_BYTES);
        if (!bytes) bytes = builtin_value(c, argv[1], SPY_BYTEARRAY);
        if (!bytes) return errorf(c, "TypeError", "a bytes-like object is required, not '%s'", type_name(argv[1]));
        size_t done = 0;
        while (done < bytes->as.string.len) {
            ssize_t n = write(fd, bytes->as.string.data + done, bytes->as.string.len - done);
            if (n < 0 && errno == EINTR) continue;
            if (n < 0) return file_error(c, errno, NULL);
            done += (size_t)n;
        }
        return spy_int(c, (int64_t)done);
    }
    int64_t n, whence = 0;
    if (index_value(c, argv[1], &n) || (id == FILE_SEEK && index_value(c, argv[2], &whence))) return NULL;
    if (id == FILE_SEEK) {
        if (whence < 0 || whence > 2) return errorf(c, "ValueError", "invalid whence (%" PRId64 ", should be 0, 1 or 2)", whence);
        off_t pos = lseek(fd, (off_t)n, whence == 0 ? SEEK_SET : whence == 1 ? SEEK_CUR : SEEK_END);
        return pos < 0 ? file_error(c, errno, NULL) : spy_int(c, (int64_t)pos);
    }
    if (id == FILE_TRUNCATE) return ftruncate(fd, (off_t)n) ? file_error(c, errno, NULL) : spy_int(c, n);
    /* FILE_READ: n bytes in one read, or everything to the end when negative. */
    size_t cap = n >= 0 ? (size_t)n : 8192, len = 0;
    char *buffer = malloc(cap ? cap : 1);
    if (!buffer) return spy_error(c, "MemoryError", "out of memory");
    for (;;) {
        if (len == cap) {
            char *grown = realloc(buffer, cap * 2);
            if (!grown) { free(buffer); return spy_error(c, "MemoryError", "out of memory"); }
            buffer = grown; cap *= 2;
        }
        ssize_t got = read(fd, buffer + len, cap - len);
        if (got < 0 && errno == EINTR) continue;
        if (got < 0) { int code = errno; free(buffer); return file_error(c, code, NULL); }
        len += (size_t)got;
        if (n >= 0 || !got) break;
    }
    SPYValue *result = spy_bytes(c, buffer, len);
    free(buffer);
    return result;
#else
    (void)argv;
    return spy_error(c, "OSError", "this build has no file system support");
#endif
}
static int file_natives(SPYContext *c, SPYValue *module) {
    static const char *const names[] = {"_file_open", "_file_read", "_file_write", "_file_seek", "_file_truncate", "_file_close"};
    for (size_t i = 0; i < sizeof(names) / sizeof(*names); i++)
        if (define_native(c, module, names[i], file_native, (void *)(intptr_t)i)) return -1;
    return 0;
}
int spy_mount(SPYContext *c, const char *directory, const char *path, int flags) {
#if SPY_FILES
    struct stat st;
    char *host = realpath(directory, NULL);
    if (!host || stat(host, &st) || !S_ISDIR(st.st_mode)) {
        errorf(c, "OSError", "cannot mount '%s': %s", directory, strerror(host ? ENOTDIR : errno));
        free(host); return -1;
    }
    if (path && path[0] != '/') { free(host); spy_error(c, "ValueError", "a mount path must be absolute"); return -1; }
    char *guest = copy_text(c, path ? path : host, strlen(path ? path : host));
    struct Mount *grown = guest ? realloc(c->mounts, (c->mounts_len + 1) * sizeof(*grown)) : NULL;
    if (!grown) { free(host); free(guest); if (!c->error_type[0]) spy_error(c, "MemoryError", "out of memory"); return -1; }
    normalize_path(guest);
    c->mounts = grown;
    c->mounts[c->mounts_len++] = (struct Mount){host, guest, flags};
    return 0;
#else
    (void)directory; (void)path; (void)flags;
    spy_error(c, "OSError", "this build has no file system support");
    return -1;
#endif
}
int spy_new_module(SPYContext *c, const char *name, SPYModuleInit init) {
    size_t i = 0;
    while (i < c->host_modules_len && strcmp(c->host_modules[i].name, name)) i++;
    if (i == c->host_modules_len) {
        struct HostModule *grown = realloc(c->host_modules, (i + 1) * sizeof(*grown));
        if (!grown) { spy_error(c, "MemoryError", "allocation failed"); return -1; }
        c->host_modules = grown;
        if (!(c->host_modules[i].name = copy_text(c, name, strlen(name)))) return -1;
        c->host_modules_len++;
    }
    c->host_modules[i].init = init;
    return 0;
}
int spy_exec_module(SPYContext *c, SPYValue *module, const char *source, const char *filename) {
    if (!same_context(c, module)) return -1;
    if (module->type != SPY_MODULE) { spy_error(c, "TypeError", "spy_exec_module() requires a module"); return -1; }
    SPYValue *unit = parse(c, source, filename ? filename : "<string>");
    if (!unit) return -1;
    Frame frame = {module, unit, 0};
    Result result = execute_module(c, &frame);
    spy_release(result.value); spy_release(unit);
    return result.flow == FLOW_ERROR ? -1 : 0;
}
void spy_set_opaque(SPYContext *c, void *opaque) { c->opaque = opaque; }
void *spy_get_opaque(const SPYContext *c) { return c->opaque; }
